ee:message.ee:set-payload:
%dw 2.0 output application/json
var customer = (vars.db default [])[0] default {}
--- { Status: "Failed", StatusCode: 200, message: "Requested data is already updated with the same details", accountNumber: vars.accountNumber, account_data: { fullname: customer.FULLNAME, mobilenumber: customer.MOBILENUMBER, address: customer.ADDRESS, accountStatus: customer.STATUS, accountCreatedOn: customer.CREATED_AT } }

%dw 2.0
output application/json
---
{
	bank_account_detailes: {
		"account_data": {
			"status": "Success",
			"statusCode": 200,
			"message": "The account has been updated successfully, and an email has been sent successfully.",
			"accountNumber": vars.accountNumber,
			"user_input_data": {
				"input_data": vars.inputpayload
			}
		}
	}
}
